WITH new_reviews(product_id,dog_breed,dog_size,coat_type,needs,summary,source_type,source_url) AS (
VALUES
('sakuradome-hugone-dog-step','ミニチュアダックスフンド',NULL,NULL,'width','別のステップから乗り換えた。幅に余裕があるぶんミニチュアダックスが上り下りしやすくなり、黒い革ソファに合う見た目と素材も気に入っている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step','ポメラニアン',NULL,NULL,'puppy chew','1.5kgのポメラニアンのソファへの飛び乗り・飛び降り対策。届いてすぐ使い始めたものの、パピー期の噛み癖でレザーがはがれてしまい、いまは対策を探しているところだそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step',NULL,NULL,NULL,'puppy height','生後10か月の犬がベッドに上がるために購入。段の高さが胸のあたりまであり、勢いをつけないと登れないのが難点。デザインと安全面には満足している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step','ポメラニアン',NULL,NULL,'scared','軽い膝蓋骨脱臼が分かった3歳のポメラニアン用。滑り止めと重さで蹴っても動かず、ホームセンターの品より作りは上だと感じている。ただ犬はまだ怖がって乗らず、使っているのは同居の猫。置くのに広さが要る点も挙げていた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step',NULL,NULL,NULL,'height durability','14kgの犬には小さめで、2段目の奥行きが足りず発泡スチロールで継ぎ足し、椅子に押し当てて固定している。小型犬なら問題ない固さだが少し沈むとのこと。表面は荒れてきたが、裂けてはいない。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step',NULL,NULL,NULL,'senior','飛び降りでぎっくり腰になった5kg弱のシニア犬のため、6個目を買って家じゅうに置いている。他社のスロープ型より使いやすく、75kgの家族が座ってもへたらない。2段に折ると使いにくい場所では2つ並べて広げて使う。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step','チワワ',NULL,NULL,'puppy scared smell','7か月のチワワ用に2個。開封時に少しカビのようなにおいがしたが、使ううちに気にならなくなった。重ねて階段状にしてもずれない。乗るのは平気でも、降りるのは怖がるので練習を続けている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step','フレンチブルドッグ',NULL,NULL,'stability','ソファへの飛び乗り・飛び降りを繰り返す15kgのフレンチブルドッグに導入。ずっしり重く、置くと安定感があり、爪の傷も付きにくそうなので長く使えると見ている。ステップを使う習慣づけはこれから。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step','ミニチュアダックスフンド',NULL,NULL,'senior','17歳・5kgのミニチュアダックスにとって初めてのステップ。後ろ足が弱っていても一段ずつゆっくりソファへ上がれていて、最初から怖がる様子もなかった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step','トイプードル',NULL,NULL,'senior','ヘルニアのある12歳のトイプードル用に2個を横並びで設置。ほかの台は使わなかったが、おもちゃで遊びながら誘導すると上り下りできるように。調子が良い日はジャンプしてしまうのが目下の悩み。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('sakuradome-hugone-dog-step',NULL,NULL,NULL,'height','2個目。安定しているので犬は迷わず登り降りする。ただ一人掛け椅子の前では高さが合わず、ベッド用に回した。もっと低いものや幅の狭いものがあれば置ける場所が増える、という要望つき。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/'),
('maxshare-dog-step-2dan',NULL,NULL,NULL,'chew stability','前のステップは角が破れ、下段がへたり、上面に穴まで開いて犬がかじったため買い替え。硬めは人が座れるほどで汚れも拭き取れる。軽くて運びやすい反面、暴れるとややずれるので、もう少し重さが欲しいという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('maxshare-dog-step-2dan','チワワ',NULL,NULL,'senior cover','3回目の購入。以前のレザーは段の角が破れたので、今回はスエードの硬めLサイズにした。高いソファ用で幅も十分あり、老犬のチワワでも安全に使えている。替えカバーの単品販売を望んでいた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('maxshare-dog-step-2dan',NULL,NULL,NULL,'vision','目の見えない犬のために購入。硬めのほうが踏みしめやすいらしく、上手に使えているとのこと。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('maxshare-dog-step-2dan',NULL,NULL,NULL,'chew','前回の布製は破れて中のスポンジが飛び出した。レザーに替えてからは汚れがすぐ取れ、犬がかじっても破れていないと満足している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('maxshare-dog-step-2dan',NULL,NULL,NULL,NULL,'リピート購入。12kgほどの犬が乗っても滑らず潰れず、PVCレザーなので飲み物をこぼしても拭けば済む。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('maxshare-dog-step-2dan',NULL,NULL,NULL,'scared','8kgの犬は踏むと沈む素材を怖がっていたが、これは沈まないので平気で乗る。底の滑り止めも効いてずれないそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('maxshare-dog-step-2dan','ミニチュアダックスフンド',NULL,NULL,'multi','ブラックの硬めを購入。サイズがちょうどよく、家のミニチュアダックスたちが問題なく上り下りしている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('maxshare-dog-step-2dan',NULL,NULL,NULL,'training','とても軽いのにずれにくく、人が腰掛けても潰れなかった。最初は警戒した犬も、フードで誘導するとすぐに使い方を覚えた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('maxshare-dog-step-2dan',NULL,NULL,NULL,'height','階段として使ってほしかったが、犬はジャンプしてしまうので広げて平らにして使っている。人が乗ってもしっかりしている点に期待しているという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/'),
('nedogko-dog-step','コーギー',NULL,NULL,'cover durability','足の短いコーギーのソファ用。6年前の本体はまだ使えるが、カバーが色あせて汚れたため同じものを買い直した。カバー単品があればうれしいこと、届いた色が画像と違って見えたことも書いている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step','シーズー',NULL,NULL,NULL,'足の短いシーズーがソファに上がれるようになり、1段目で寝ていることも。値段は高めに感じ、同居猫の引っかきに強い生地なら星5だったそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step',NULL,NULL,NULL,'washable','3つ目の購入。いちばん古いものはファスナーが壊れて買い替えた。滑り止めが効き、カバーは洗えてウレタンにも防水カバーがあるので、吐き戻しや下痢、うれションで汚れても使い続けられる。カバー単品の販売も望んでいた。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step','トイプードル',NULL,NULL,'puppy scared','生後5か月・4.5kgのトイプードル用に、高さ約50cmのベッドへ2セット。最初は怖がったが、おもちゃで誘導すると使うようになった。ジャンプでも登れてしまうので1セットで足りたかもしれない、とも。足は滑らず、ステップも動かない。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step',NULL,'medium',NULL,'senior slip','降り口に合うワイドを選び、フローリングの保護マットの上でもずれない。前の他社の幅40cmより軽く、ウレタンも柔らかめ。13kgのシニア中型犬が小走りで降りて一度滑り、けがはなかったがその後は気をつけている。介助なしで降りられるようになった。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step',NULL,NULL,NULL,'scared multi','2匹が出窓に上り下りする用。1個では上らず、もう1個足して3段にすると、好奇心の強い子はすぐ、臆病な子も3日目には使えた。段を増やしたほうが怖がらないようだ。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step',NULL,NULL,NULL,'stability','膝蓋骨脱臼で後ろ足が弱い犬のため、前の他社品が動いて不安定だったことから安全性重視で選んだ。届いてすぐ使い、ジャンプしても沈み込まない硬さ。カバーを外して洗える点も評価している。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step',NULL,NULL,NULL,'multi','4匹のため、高さ約50cmの収納兼畳コーナーの上り下り用に。最初はためらっていたが、人のまねをするうちに自然と使うようになった。欲しい色が売り切れでグレーにしたが、部屋になじんでいる。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step',NULL,NULL,NULL,'puppy','膝の手術をしたばかりの仔犬が、スロープ代わりに重宝している。居心地もいいようで、寝そべってくつろぐ姿も見られる。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('nedogko-dog-step',NULL,NULL,NULL,NULL,'ヘルニアになった犬の上り下りを少しでも楽にしたくて購入。高さも硬さも期待どおりで、届いてすぐ2個を追加した。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/'),
('cellutane-a387-dog-step-4dan','ミニチュアダックスフンド',NULL,NULL,'senior stability','発泡スチロール入りの踏み台は左右にぐらつき、14歳のミニチュアダックスはあまり登らなかった。こちらは安定していて軽快に登るように。値段は高めでも満足度は高い。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan',NULL,NULL,NULL,'senior','段差がゆるやかで、2段のときのジャンプ気味の登り方がなくなった高齢犬。汚れを拭けるのは便利だが、綿素材を望んでいたので星4。綿のほうが滑りにくいのでは、とも書いている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan','ダックスフンド',NULL,NULL,'senior slip','2段を使っていた16歳のダックスが後ろ足の衰えで登りにくくなり買い替え。生地が滑りやすく、最初は足を滑らせながら登っていたが、滑り止めシートを貼ってからはうまく登れている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan','トイプードル',NULL,NULL,'multi width','3段を持っていて追加購入。5kgの子は3段でも余裕だが、2.8kgの子は跳ねて登るのでダックス向けの4段を試した。2台並べて幅を出し、斜めに上り下りできるようにするほうが段数より効くと感じたそうだ。高価なのでお試しがあれば、という声も。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan','カニンヘンダックスフンド',NULL,NULL,'senior stability','手術後の11歳のカニンヘンダックス用。段差が低くジャンプせず上がれ、ステップも動かず、クッションの固さもほどよい。以前の約3000円のステップは不安定で捨てたので、この価格には納得している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan','ダックスフンド',NULL,NULL,'multi slip','ダックス2頭の家で3つ目のステップ。軽くて移動や掃除は楽。ただ段のゆるいカーブ部分で足を滑らせたため、4段すべてに滑り止めを貼って対処した。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan','チワワ',NULL,NULL,'senior vision','白内障のある13歳のチワワに、段差の少ない4段を選んだ。段が見えにくいかもしれないと各段にマスキングテープを貼っている。踏み面はもう少し広いと理想的だった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan','柴犬',NULL,NULL,'scared slip','8歳・20kgの柴犬のソファ乗り降り用。臆病な子なのでおやつを置いて慣らした。丈夫でへこまず、拭くだけで汚れが落ちる。勢いよく飛び降りるとずれるので、下に滑り止めシートを敷いている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan',NULL,NULL,NULL,'senior multi width','思ったより軽く、やんちゃな子が飛び跳ねるように乗るとずれる。上の老犬は幅の狭さが怖かったのか使わず、2台並べることにした。素材の高級感と拭ける点は良いが、値段の割には、という感想。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/'),
('cellutane-a387-dog-step-4dan',NULL,NULL,NULL,'slip','滑るという声を承知のうえで、若い犬なので購入したが、実際に少し滑る。ヴィンテージグレーは写真より濃い。サイズは大きいがダックスの胴の長さを考えれば妥当で、子どもが乗ると早くへたりそうな柔らかさだという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/')
)
INSERT INTO reviews(product_id,dog_breed,dog_size,coat_type,needs,summary,source_type,source_url)
SELECT n.product_id,n.dog_breed,n.dog_size,n.coat_type,n.needs,n.summary,n.source_type,n.source_url
FROM new_reviews n
WHERE NOT EXISTS (
  SELECT 1 FROM reviews r
  WHERE r.product_id=n.product_id
    AND r.summary=n.summary
);

WITH new_reviews(product_id,dog_breed,dog_size,coat_type,needs,summary,source_type,source_url) AS (
VALUES
('kirara-dog-slope-wide','チワワ',NULL,NULL,'slope','膝蓋骨脱臼のあるチワワの足を守るため、ゆるい傾斜のものを探して2段を購入。勢いをつけなくても歩いて登れ、耐久性もあると感じている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide','ポメラニアン',NULL,NULL,'senior training','今年10歳のポメラニアンの先を考えて初めて導入し、教えながら少しずつ使えるように。高さ28cmの3段Aがソファに合い、段差もきつくない。カバー生地のよれが気になって星4にした。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide',NULL,NULL,NULL,'stability','フローリングに直置きすると裏の滑り止めは弱め。軽くて移動は楽な一方、昇り降りで少し動いて不安定に感じる。降りるときはスロープを飛び越えてしまうので、慣れてほしいとのこと。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide','トイプードル',NULL,NULL,'senior','高さ40cmの3段B。12歳のトイプードルは手を添えれば登れるが、降りるときは飛び降りてしまい、練習しても使ってもらえなかった。本体はしっかりしているものの軽い。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide','キャバリア',NULL,NULL,'senior multi','9歳のキャバリアの膝の予防に、3段Bを2台並べて横からの飛び降りを防いでいる。ソファとほぼ同じ高さで初日から無理なく使え、4歳の子は遊具のように駆け上がる。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide','トイプードル',NULL,NULL,'senior','使い始めて2か月。慣れるまで時間がかかり、15歳のトイプードルはいまは降りるときだけ使って、上りはまだ跳び上がる。軽くてずれやすいのが気になるが、降りるときだけでも使ってくれて良かったという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide','フレンチブルドッグ',NULL,NULL,'puppy','フレンチブルドッグの子犬のソファ用。おやつで練習するとすぐ使ったが、降りる側が少し急で、お腹で滑るように降りている。ファスナーが気になっていたずらするので中にしまい込んだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide','トイプードル',NULL,NULL,'senior','13歳のトイプードル用。最初は使いこなせなかったが、いまは傾斜をすたすた駆け上がり、体に負担をかけずに済んでいる。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide','ダックスフンド',NULL,NULL,NULL,'ヘルニアの手術歴があるダックスフンド用に2段を。ソファへの乗り降りに無理がないのがありがたいそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('kirara-dog-slope-wide','ミニチュアダックスフンド',NULL,NULL,'puppy','ソファから飛び降りる子犬のミニチュアダックスのため、背の高い3段Bを選択。ソファの色と合い、部屋にもおしゃれに収まった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/'),
('sumica-a242-pet-step','チワワ',NULL,NULL,'senior vision','白内障で目が見えない16歳のチワワ用に買い替え。前の階段は踏み面が狭く、下りで転げ落ちることがあった。最初の数日は体を支え、1週間ほどで自力で上り下りできるようになった。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step','チワワ',NULL,NULL,'chew','収納ボックスで代用していた高いベッドへの段差用。設置するとすぐ喜んで使った。ファスナーが内側にあって噛まれにくく、布カバーで滑りにくい。毛はかなり付くが、安全を優先してこれにして正解だったという。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step',NULL,NULL,NULL,'height','届いた直後は表示の高さ30cmに届かず25cmほどで星3にしたが、1か月使って犬が使いやすそうなので星5に改めた。1歳の子どももソファの上り下りに使っているとのこと。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step','カニンヘンダックスフンド',NULL,NULL,'height','4kg弱のカニンヘンダックス。潰れた状態で届いたが、2週間ほどで各段が約10.5・20・29.5cmに戻った。硬さはほどよく、夜も見やすい色で良かった。興奮するとソファから飛び降りそうになるので注意している。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step','チワワ',NULL,NULL,'durability slip','合成レザーの階段で滑って落ち、大けがをしたチワワのため布製を選んだ。すぐ膨らみ滑りにくいが、半年ほどで生地が削れて糸が出て、その糸を食べてしまうので処分した。カバーだけ交換できれば、と書いている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step','ミニチュアダックスフンド',NULL,NULL,'chew','胴が長いので3段を選んだ9歳のミニチュアダックス。少し噛む癖があるがちぎれる心配はなさそう。勢いよく降りて転びかけてからは横向きに降りるようになった。色は思ったより黄色みが強かった。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step',NULL,NULL,NULL,'softness','2.7kgの犬なら沈まないが、大きい犬だと沈んで登るときに膝へ負担がかかりそう、という見立て。圧縮で布団のように小さく届き、カバーは薄いパイル地で滑りにくそう。天面が擦れて傷まないかを気にしている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step','柴犬',NULL,NULL,'width','他社品は座面が狭くて使わなかった7kgの柴犬。超小型犬の口コミが多く沈むか心配したが沈み込みはなく、一段ごとが低くて登りやすい。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step','ポメラニアン、チワワ',NULL,NULL,'senior multi','シニアのポメラニアン（4kg）用に買ったのに、2.5kgのチワワのほうがよく使っている。人が片足で乗るとよく沈むがすぐ戻る。噛み防止のためか、チャックは奥に入り込んでいて分かりにくい。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('sumica-a242-pet-step','ダックスフンド',NULL,NULL,'senior width','10歳を過ぎて幅の狭い階段や急なスロープがつらそうになったダックスのため、幅広のこちらに。もともと慣れていたのでスムーズに使えたが、高さがもう少しあればうれしいという。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/'),
('petfun-dog-step-2dan','ポメラニアン',NULL,NULL,'senior multi','シニアになったポメラニアン2匹のため、リビングとダイニングの間にある30cmの段差に設置。すぐに上り下りでき、洗濯できるのも使いやすそうだと感じている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan',NULL,NULL,NULL,'slip multi','犬と猫が走り回ってもずれにくい滑り止め。圧縮で届き、30分ほどで元の形に戻った。防水カバーのせいか犬が少し滑るが、二重の防水カバーは安心で、価格はやや高めでも満足している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan',NULL,NULL,NULL,NULL,'7kgの犬が乗っても支えてくれる厚みと弾力があり、においも気にならない。すぐ乗ってベッド代わりにしているが、階段としてはまだ使っておらず、幅が広いので足元は不安になりにくそうだと見ている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan','チワワ',NULL,NULL,'slip','高さ52cmのベッドへ上り下りするチワワ用。勢いよく使うと防水カバーが滑って怖がったので、バスタオルで覆ったところ滑らなくなった。色は写真どおりのきれいなグレー。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan','トイプードル',NULL,NULL,NULL,'4kgのトイプードルがベッドの上り下りに使うようになり、負担をかけずに済むので安心だとしている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan','チワワ',NULL,NULL,'senior','足腰が弱ってきた13歳のチワワ。段差がちょうど合うようで、無理なく登れている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan','カニンヘンダックスフンド',NULL,NULL,'training','初めてのステップで、カニンヘンダックスはまだ使ったり使わなかったり。おやつで慣らしつつ、慣れたら買い足しも考えている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan',NULL,NULL,NULL,NULL,'ソファ用の1台がうまくいったので、より高いベッド用に2台を追加して3段に。2.5kgの犬は今回もスムーズに上り下りし、足への負担がなさそうで安心している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan',NULL,NULL,NULL,'washable multi','2頭目を迎えて粗相が増え、撥水のステップを探して購入。外カバーも内カバーも撥水で、さっそくおしっこをされたが全く染みていなかった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('petfun-dog-step-2dan',NULL,NULL,NULL,'training','飛び上がるのをためらうようになった犬が昼寝するベッド用。軽くてしっかりした素材だが、届いて2日で登ったのは1回だけで、慣れるのを待っている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/'),
('kirara-dog-step-storage-3dan','ダックスフンド',NULL,NULL,'storage','ベッドから頻繁に飛び降りるダックスフンドの脚や腰が心配で購入。段差は10cmで昇降が楽そうに見え、収納ボックスとして使える点も評価している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan','ボーダーコリー',NULL,NULL,'puppy stability','ボーダーコリーの子犬がすぐに使って上がってくるようになった。成長後も物入れとして役立ちそうな一方、走って上り下りするとクッションフロアの上で本体を蹴り飛ばしてしまうので、底に滑り止めが欲しいという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan',NULL,NULL,NULL,'chew multi','収納は便利だが、男の子の犬はふたを噛んだり外したりして遊んでしまう。女の子はそうしないので、ふたが外れにくい作りなら長持ちしそうだと書いている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan',NULL,NULL,NULL,'senior stability','シニア犬用に購入し、値段を考えれば満足。降りるときに前へ少し揺れたが、3段目の収納に重りを入れて解消した。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan','コーギー',NULL,NULL,'stability','16kgのコーギーでもしっかり上り下りできている。本体がとても軽いので、フードなど重い物を入れて安定させている。手頃な価格ゆえに耐久性は少し心配だという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan','マルチーズ×チワワ',NULL,NULL,'scared','膝蓋骨脱臼と診断された9歳・4.5kgのマルチーズ×チワワのソファ用。最初は怖がったが、抱っこで乗せるのを数回繰り返すと少しずつ使うように。安定感があり、収納もそこそこ入る。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan',NULL,NULL,NULL,'stability','犬が自由にソファへ上り下りでき、おもちゃ入れにもなる。勢いよく使うとふたがずれるのでマジックテープなどで留めるとよく、フローリングでは滑るため滑り止めマットを敷いて落ち着いた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan',NULL,NULL,NULL,'senior smell','11年一緒に暮らす犬が、おやつで覚えていまはベッドに上がるたびに使う。最初はにおいがきつかったがすぐ消えた。軽いので滑り止めマットの上に置き、最上段に1.5Lのペットボトルを入れている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan',NULL,'small',NULL,'senior smell','前の階段を高く感じて登らなくなった18歳・4kgの小型犬が、すぐ登ってくれた。生地も滑りにくい。グレーの色味は微妙で、においも独特。中に物を入れると安定するとのこと。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('kirara-dog-step-storage-3dan','ミニチュアダックスフンド',NULL,NULL,'senior durability','もうすぐ15歳になる3.6kgのミニチュアダックスがベッドから飛び降りるようになり、急いで購入。最初はへっぴり腰でもすぐ慣れた。作りはしっかりしているが、あと半年もてば、と耐久性にはやや不安を残している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/')
)
INSERT INTO reviews(product_id,dog_breed,dog_size,coat_type,needs,summary,source_type,source_url)
SELECT n.product_id,n.dog_breed,n.dog_size,n.coat_type,n.needs,n.summary,n.source_type,n.source_url
FROM new_reviews n
WHERE NOT EXISTS (
  SELECT 1 FROM reviews r
  WHERE r.product_id=n.product_id
    AND r.summary=n.summary
);

WITH new_reviews(product_id,dog_breed,dog_size,coat_type,needs,summary,source_type,source_url) AS (
VALUES
('kirara-dog-step-storage-3dan',NULL,NULL,NULL,'height','別の店の2段ではベッドに高さが足りず、降りるのを怖がっていた。3段のこちらに替えるとスムーズに乗り降りし、6kgの犬が乗ってもしっかりしている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/'),
('nedogko-dog-step-low','コーギー',NULL,NULL,'puppy chew','ソファに登れても降りられなかった子犬のコーギーが、いまは軽快に上り下り。短足の犬にもやさしい低さで、噛まれても生地が破れず、ファスナーを隠せるのも安心材料になっている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','マルチーズ','small',NULL,'multi stability','膝の手術後のマルチーズ2匹のためにロータイプを選び、生地とウレタンの固さも合った。高さ約27cmのベッドにはロー1つで足り、約35cmのソファには2つ重ねる。畳や絨毯の上では底の滑り止めでも動くので、はがせるテープで固定している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','ビーグル',NULL,NULL,'senior training','ヘルニアと診断された11歳のビーグルのため、ロー2つを組み合わせて3段に。おやつで誘導して覚え、いまは自分で上り下りする。ステップを通らないと行けない位置に置いたのも工夫のひとつ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','プードル',NULL,NULL,'scared','胴長短足の8歳のプードル。一番上の段は奥行きが狭くて怖がり、上段には乗らずにソファへ飛び乗ってしまう。色違いを2つ並べたら色の差が目立ったのも残念だったという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','ダックスフンド',NULL,NULL,'senior','段の間隔が狭い3段ステップでは踏み外していたシニアのダックス。間隔に余裕ができて登りやすくなったが、後ろ足のまひで最後の足が引っかかることがあり、タオルで坂を作ることを考えている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','トイプードル',NULL,NULL,'senior stability','白内障もある14歳のトイプードル用に、高さ15cmのステップから買い替えて2個で3段に。踏み込みが広く調子はよいが、前のレザーより汚れが拭きにくく、軽すぎて動くのが惜しい点として挙がっていた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','ダックスフンド',NULL,NULL,'height','約7kgのダックスは、上りはいまも飛び乗るが、降りるときはステップを使うようになった。段が短いのか降りにくそうで、もう少し長さがあるとよいという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','ダックスフンド',NULL,NULL,'senior scared','段差で滑り落ちた老犬のダックスのために買ったが、バリケードと思ったのか、いまのところ登らない。段が低く滑りにくい点、マットが硬めな点は気に入っている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','ダックスフンド',NULL,NULL,'height','階段状にすると上の段が短くて嫌がったが、1段に広げたら上り下りするように。くつろぎや昼寝の場所にもなっていて、2段目が長ければリピートしたいそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low',NULL,NULL,NULL,'senior softness','ベッドに上がれなくなりつつある18歳の犬のため、薄くて柔らかめの段で高さを調整。形が変わって戸惑う場面はあるが、滑って危なっかしい感じはなくなった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('nedogko-dog-step-low','ミニチュアダックスフンド',NULL,NULL,'multi cover','ミニチュアダックス2頭と猫1匹の家で、2頭が同時に乗っても安全なように2つ買い足した。猫が爪をといでもきれいで合皮より丈夫だが、カバーは洗うと乾きにくく少し縮む。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/'),
('cellutane-a385-dog-step-2dan',NULL,NULL,NULL,'stability','飛び降りがなくなり、犬も快適に使っている。高さ約33cmの幅広タイプで、ベッドと合わせて3段の階段のように。生地のよれと、底が滑り止め仕様でない点は残念で、別に滑り止めを敷くと勢いよく上っても動かなくなった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/'),
('cellutane-a385-dog-step-2dan','チワプー',NULL,NULL,'puppy','ソファへジャンプして危ない生後3か月のチワプー用。届いてすぐ使い始め、暑い日は1段目のひんやりした感触を気に入って昼寝している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/'),
('cellutane-a385-dog-step-2dan','マルプー',NULL,NULL,'width','前の幅が狭く段差の高いステップは上りにしか使わなかった5kgのマルプー。こちらは段差がゆるく幅もあり、怖がらずに上り下りできた。大きいが一人で動かせる重さだという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/'),
('cellutane-a385-dog-step-2dan','トイプードル',NULL,NULL,'multi scared','トイプードル2匹のうち1匹はすぐ使い、警戒したもう1匹もおやつで一段ずつ慣らすとすぐ覚えた。滑ってはいないが、念のためビニール床対応の犬用滑り止めワックスを自己責任で塗った。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/'),
('cellutane-a385-dog-step-2dan',NULL,NULL,NULL,'scared cover','慎重な性格で最初は使わず、おやつで誘導していたが、ソファ用の布をかぶせたら使い始めた。素材自体は滑りやすくないが、カバーがあると安心するらしく自作したそうだ。軽くて移動は楽、価格はやや高め。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/'),
('cellutane-a385-dog-step-2dan',NULL,NULL,NULL,'puppy','小上がりの和室に飛び乗る子犬に、早いうちから慣れてほしくて購入。まだおやつで釣らないと乗らない。奥行きを考えずに買ったので縦に長く、部屋に圧迫感がある。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/'),
('cellutane-a385-dog-step-2dan','マルチーズ',NULL,NULL,'senior','ソファからうまく着地できなくなったハイシニアのマルチーズ。簡易の段差と併用して時々登っていて、降りるのも覚えてほしいところ。滑るかと思ったがクッションの弾力で問題なかった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/'),
('cellutane-a385-dog-step-2dan',NULL,NULL,NULL,'scared training','左後ろ足が弱い犬のために購入。商品は良いと思うが、まだ警戒して近寄らず、おやつやおもちゃで少しずつ教えていく予定。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/'),
('chikyutonya-dog-step-wide55',NULL,'large',NULL,'senior','後ろ脚の踏ん張りが弱くなった大型の高齢犬のため、ベランダへの段差に設置。幅広のハードタイプなので、大型犬が乗っても沈み込まず安心して使えている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('chikyutonya-dog-step-wide55','トイプードル',NULL,NULL,'senior stability','変形性脊椎症のある12歳・4kgのトイプードル。以前のスロープはわずかなぐらつきを嫌がり、とくに上りで使わなかった。幅広で重さのあるこちらは初日から上り下りでき、汚れもさっと拭ける。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('chikyutonya-dog-step-wide55','コーギー',NULL,NULL,'stability','走り回ってソファまで使う10kgのコーギーの段差対策。まったくずれずしっかりしているが、グレーが思ったより濃く、ホワイトにすればよかったと少し後悔している。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('chikyutonya-dog-step-wide55',NULL,NULL,NULL,'width','作りはしっかりしているが、うちの犬には上段の幅が足りないようで、2つ買い足して幅を広げる予定。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('chikyutonya-dog-step-wide55','チワワ',NULL,NULL,'puppy multi','シニアのチワワとパピーがいて、パピーのソファからの飛び降りを止めたくて、沈まない硬めを選んだ。2匹ともすぐ使って飛び降りがなくなった。黒はほこりや毛が目立つが、インテリアには合う。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('chikyutonya-dog-step-wide55','ダックスフンド',NULL,NULL,'height','幅の狭い階段はあるが、とっさに飛び降りてしまうダックス。ヘルニアや脚が心配で、ワイドで段差の低いこれを選んだ。1つでは高さが少し足りないので、もう1つ買う予定。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('chikyutonya-dog-step-wide55','ポメラニアン',NULL,NULL,'durability','約3kgのポメラニアン。布カバーの3段がぼろぼろになり、販売終了だったので乗り換えた。3段にするには2つ要り少し高くなったが、幅広で硬さもある。160サイズで宅配ボックスに入らず、営業所で受け取った。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('chikyutonya-dog-step-wide55',NULL,NULL,NULL,'senior','いままでの階段を登れなくなった11歳の犬のため、2つで3段にして使用。幅が広く硬めなので沈まず、一段ずつしっかり登れている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('chikyutonya-dog-step-wide55','マルチーズ',NULL,NULL,'puppy','生後4か月のマルチーズがすぐに使い方を理解し、飛び降りをしなくなった。膝を守りながら暮らせそうだと感じている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/'),
('petfun-urbantail-wood-slope','トイプードル',NULL,NULL,'scared training','階段を怖がっていたトイプードルが、おやつを使った約3週間の練習で4段を自分から使うように。木の土台がしっかりしていて克服に向いていた。階段下のスペースは怖がって入らず、防災袋の置き場にする予定。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/'),
('petfun-urbantail-wood-slope','ダックスフンド',NULL,NULL,'slope','飛び降り防止に3段を設置。リビングでも浮かない見た目だが、角度がもう少しゆるく、幅の広いタイプもあれば、と星4。設置後も途中から飛び降りるので、使う癖づけを続けている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/'),
('petfun-urbantail-wood-slope','プードル',NULL,NULL,'assembly','3段なのに4段用の説明書が入っていて穴の数に戸惑い、動画とも手順が少し違ったが、一人で約1時間で組み立てた。高いベッドから飛び降りる3kgのプードルが数日で使うように。天板がはずみで外れることがあり、星を1つ減らした。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/'),
('petfun-urbantail-wood-slope','ジャックラッセルテリア',NULL,NULL,'senior','今年17歳になるジャックラッセルがベッドやソファに上がれるように購入し、いまは登る練習中。作りはしっかりしていて、組み立ても簡単だった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/'),
('petfun-urbantail-wood-slope','トイプードル',NULL,NULL,'senior scared slip','傾斜が急でやや滑るものの、臆病な13歳のトイプードルもどうにか登れるようになった。作りはしっかりしていて安心感がある。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/'),
('petfun-urbantail-wood-slope','トイプードル',NULL,NULL,'senior multi','なだらかなスロープで、14歳のトイプードルが使えている。2歳の子も飛び乗って使うが、しっかりしていて問題ない。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/'),
('petfun-urbantail-wood-slope',NULL,NULL,NULL,'slope','女性一人でも組み立てられた。犬は最初おそるおそるで、少しずつ慣れてきたがまだ降りることはできない。飼い主が自分で試すと急斜面に感じて怖かった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/'),
('petfun-urbantail-wood-slope',NULL,NULL,NULL,'assembly','ネジ穴が2か所開いておらず、自宅の電動ドライバーでなんとか取り付けた。昇降用に買ったのに、クッションが心地よいのか犬は一番上でくつろいでいる。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/'),
('petfun-urbantail-wood-slope','チワワ',NULL,NULL,'senior slip','ネジが入らない穴があり耐久性が不安。足の悪い12歳のチワワは登り降りで滑り、百均の滑り止めを貼っても自分からは使わない。傾斜の急さが原因と見ていて、他社のゆるいスロープは使えたという。拭けて滑りにくい素材を望んでいた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/')
)
INSERT INTO reviews(product_id,dog_breed,dog_size,coat_type,needs,summary,source_type,source_url)
SELECT n.product_id,n.dog_breed,n.dog_size,n.coat_type,n.needs,n.summary,n.source_type,n.source_url
FROM new_reviews n
WHERE NOT EXISTS (
  SELECT 1 FROM reviews r
  WHERE r.product_id=n.product_id
    AND r.summary=n.summary
);

WITH new_sources(product_id,summary,source_type,source_url,source_platform,source_review_id) AS (
VALUES
('sakuradome-hugone-dog-step','別のステップから乗り換えた。幅に余裕があるぶんミニチュアダックスが上り下りしやすくなり、黒い革ソファに合う見た目と素材も気に入っている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20260530:482b8f69:o20260427:s5'),
('sakuradome-hugone-dog-step','1.5kgのポメラニアンのソファへの飛び乗り・飛び降り対策。届いてすぐ使い始めたものの、パピー期の噛み癖でレザーがはがれてしまい、いまは対策を探しているところだそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20260206:482b8f69:o20260128:s5'),
('sakuradome-hugone-dog-step','生後10か月の犬がベッドに上がるために購入。段の高さが胸のあたりまであり、勢いをつけないと登れないのが難点。デザインと安全面には満足している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20260627:8c073447:o20260620:s4'),
('sakuradome-hugone-dog-step','軽い膝蓋骨脱臼が分かった3歳のポメラニアン用。滑り止めと重さで蹴っても動かず、ホームセンターの品より作りは上だと感じている。ただ犬はまだ怖がって乗らず、使っているのは同居の猫。置くのに広さが要る点も挙げていた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20261015:ec80e9cc:o20260905:s4'),
('sakuradome-hugone-dog-step','14kgの犬には小さめで、2段目の奥行きが足りず発泡スチロールで継ぎ足し、椅子に押し当てて固定している。小型犬なら問題ない固さだが少し沈むとのこと。表面は荒れてきたが、裂けてはいない。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20260816:482b8f69:o20260805:s4'),
('sakuradome-hugone-dog-step','飛び降りでぎっくり腰になった5kg弱のシニア犬のため、6個目を買って家じゅうに置いている。他社のスロープ型より使いやすく、75kgの家族が座ってもへたらない。2段に折ると使いにくい場所では2つ並べて広げて使う。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20260723:482b8f69:o20260720:s5'),
('sakuradome-hugone-dog-step','7か月のチワワ用に2個。開封時に少しカビのようなにおいがしたが、使ううちに気にならなくなった。重ねて階段状にしてもずれない。乗るのは平気でも、降りるのは怖がるので練習を続けている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20260702:482b8f69:o20260629:s4'),
('sakuradome-hugone-dog-step','ソファへの飛び乗り・飛び降りを繰り返す15kgのフレンチブルドッグに導入。ずっしり重く、置くと安定感があり、爪の傷も付きにくそうなので長く使えると見ている。ステップを使う習慣づけはこれから。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20260205:c7896687:o20260120:s5'),
('sakuradome-hugone-dog-step','17歳・5kgのミニチュアダックスにとって初めてのステップ。後ろ足が弱っていても一段ずつゆっくりソファへ上がれていて、最初から怖がる様子もなかった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20261126:482b8f69:o20261015:s5'),
('sakuradome-hugone-dog-step','ヘルニアのある12歳のトイプードル用に2個を横並びで設置。ほかの台は使わなかったが、おもちゃで遊びながら誘導すると上り下りできるように。調子が良い日はジャンプしてしまうのが目下の悩み。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20261117:f01087bf:o20261108:s5'),
('sakuradome-hugone-dog-step','2個目。安定しているので犬は迷わず登り降りする。ただ一人掛け椅子の前では高さが合わず、ベッド用に回した。もっと低いものや幅の狭いものがあれば置ける場所が増える、という要望つき。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/284145_10012672/1.1/','rakuten','284145_10012672:20261028:482b8f69:o20261015:s5'),
('maxshare-dog-step-2dan','前のステップは角が破れ、下段がへたり、上面に穴まで開いて犬がかじったため買い替え。硬めは人が座れるほどで汚れも拭き取れる。軽くて運びやすい反面、暴れるとややずれるので、もう少し重さが欲しいという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20260902:482b8f69:o20260822:s4'),
('maxshare-dog-step-2dan','3回目の購入。以前のレザーは段の角が破れたので、今回はスエードの硬めLサイズにした。高いソファ用で幅も十分あり、老犬のチワワでも安全に使えている。替えカバーの単品販売を望んでいた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20260717:482b8f69:o20260715:s4'),
('maxshare-dog-step-2dan','目の見えない犬のために購入。硬めのほうが踏みしめやすいらしく、上手に使えているとのこと。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20260910:30fbbbb1:o20260906:s5'),
('maxshare-dog-step-2dan','前回の布製は破れて中のスポンジが飛び出した。レザーに替えてからは汚れがすぐ取れ、犬がかじっても破れていないと満足している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20260213:482b8f69:o20251227:s5'),
('maxshare-dog-step-2dan','リピート購入。12kgほどの犬が乗っても滑らず潰れず、PVCレザーなので飲み物をこぼしても拭けば済む。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20251224:e6343e45:o20251210:s5'),
('maxshare-dog-step-2dan','8kgの犬は踏むと沈む素材を怖がっていたが、これは沈まないので平気で乗る。底の滑り止めも効いてずれないそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20241231:482b8f69:o20241219:s5'),
('maxshare-dog-step-2dan','ブラックの硬めを購入。サイズがちょうどよく、家のミニチュアダックスたちが問題なく上り下りしている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20251101:a583235d:o20251021:s5'),
('maxshare-dog-step-2dan','とても軽いのにずれにくく、人が腰掛けても潰れなかった。最初は警戒した犬も、フードで誘導するとすぐに使い方を覚えた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20251002:69ec5a26:o20250929:s5'),
('maxshare-dog-step-2dan','階段として使ってほしかったが、犬はジャンプしてしまうので広げて平らにして使っている。人が乗ってもしっかりしている点に期待しているという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/201798_10055683/1.1/','rakuten','201798_10055683:20260915:482b8f69:o20260911:s4'),
('nedogko-dog-step','足の短いコーギーのソファ用。6年前の本体はまだ使えるが、カバーが色あせて汚れたため同じものを買い直した。カバー単品があればうれしいこと、届いた色が画像と違って見えたことも書いている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260626:52390ca6:o20260625:s4'),
('nedogko-dog-step','足の短いシーズーがソファに上がれるようになり、1段目で寝ていることも。値段は高めに感じ、同居猫の引っかきに強い生地なら星5だったそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260521:4fdd2498:o20260511:s4'),
('nedogko-dog-step','3つ目の購入。いちばん古いものはファスナーが壊れて買い替えた。滑り止めが効き、カバーは洗えてウレタンにも防水カバーがあるので、吐き戻しや下痢、うれションで汚れても使い続けられる。カバー単品の販売も望んでいた。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260430:ecf55a86:o20260420:s5'),
('nedogko-dog-step','生後5か月・4.5kgのトイプードル用に、高さ約50cmのベッドへ2セット。最初は怖がったが、おもちゃで誘導すると使うようになった。ジャンプでも登れてしまうので1セットで足りたかもしれない、とも。足は滑らず、ステップも動かない。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20261006:138858d6:o20261002:s5'),
('nedogko-dog-step','降り口に合うワイドを選び、フローリングの保護マットの上でもずれない。前の他社の幅40cmより軽く、ウレタンも柔らかめ。13kgのシニア中型犬が小走りで降りて一度滑り、けがはなかったがその後は気をつけている。介助なしで降りられるようになった。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260604:482b8f69:o20260524:s4'),
('nedogko-dog-step','2匹が出窓に上り下りする用。1個では上らず、もう1個足して3段にすると、好奇心の強い子はすぐ、臆病な子も3日目には使えた。段を増やしたほうが怖がらないようだ。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260716:482b8f69:o20260711:s5'),
('nedogko-dog-step','膝蓋骨脱臼で後ろ足が弱い犬のため、前の他社品が動いて不安定だったことから安全性重視で選んだ。届いてすぐ使い、ジャンプしても沈み込まない硬さ。カバーを外して洗える点も評価している。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260410:e8b31e02:o20260328:s5'),
('nedogko-dog-step','4匹のため、高さ約50cmの収納兼畳コーナーの上り下り用に。最初はためらっていたが、人のまねをするうちに自然と使うようになった。欲しい色が売り切れでグレーにしたが、部屋になじんでいる。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260125:482b8f69:o20260111:s5'),
('nedogko-dog-step','膝の手術をしたばかりの仔犬が、スロープ代わりに重宝している。居心地もいいようで、寝そべってくつろぐ姿も見られる。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260611:4a7e6c3f:o20260605:s5'),
('nedogko-dog-step','ヘルニアになった犬の上り下りを少しでも楽にしたくて購入。高さも硬さも期待どおりで、届いてすぐ2個を追加した。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/355438_10000313/1.1/','rakuten','355438_10000313:20260406:02b014af:o20260403:s5'),
('cellutane-a387-dog-step-4dan','発泡スチロール入りの踏み台は左右にぐらつき、14歳のミニチュアダックスはあまり登らなかった。こちらは安定していて軽快に登るように。値段は高めでも満足度は高い。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20260923:6decfc8e:o20260905:s5'),
('cellutane-a387-dog-step-4dan','段差がゆるやかで、2段のときのジャンプ気味の登り方がなくなった高齢犬。汚れを拭けるのは便利だが、綿素材を望んでいたので星4。綿のほうが滑りにくいのでは、とも書いている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20260512:e0d35c66:o20260430:s4'),
('cellutane-a387-dog-step-4dan','2段を使っていた16歳のダックスが後ろ足の衰えで登りにくくなり買い替え。生地が滑りやすく、最初は足を滑らせながら登っていたが、滑り止めシートを貼ってからはうまく登れている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20220423:482b8f69:o20220416:s4'),
('cellutane-a387-dog-step-4dan','3段を持っていて追加購入。5kgの子は3段でも余裕だが、2.8kgの子は跳ねて登るのでダックス向けの4段を試した。2台並べて幅を出し、斜めに上り下りできるようにするほうが段数より効くと感じたそうだ。高価なのでお試しがあれば、という声も。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20180406:482b8f69:o20180403:s5'),
('cellutane-a387-dog-step-4dan','手術後の11歳のカニンヘンダックス用。段差が低くジャンプせず上がれ、ステップも動かず、クッションの固さもほどよい。以前の約3000円のステップは不安定で捨てたので、この価格には納得している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20180213:482b8f69:o20180205:s5'),
('cellutane-a387-dog-step-4dan','ダックス2頭の家で3つ目のステップ。軽くて移動や掃除は楽。ただ段のゆるいカーブ部分で足を滑らせたため、4段すべてに滑り止めを貼って対処した。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20191031:05ae877f:o20191025:s5'),
('cellutane-a387-dog-step-4dan','白内障のある13歳のチワワに、段差の少ない4段を選んだ。段が見えにくいかもしれないと各段にマスキングテープを貼っている。踏み面はもう少し広いと理想的だった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20180322:482b8f69:o20180304:s5'),
('cellutane-a387-dog-step-4dan','8歳・20kgの柴犬のソファ乗り降り用。臆病な子なのでおやつを置いて慣らした。丈夫でへこまず、拭くだけで汚れが落ちる。勢いよく飛び降りるとずれるので、下に滑り止めシートを敷いている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20210710:8cbfdcaf:o20210706:s5'),
('cellutane-a387-dog-step-4dan','思ったより軽く、やんちゃな子が飛び跳ねるように乗るとずれる。上の老犬は幅の狭さが怖かったのか使わず、2台並べることにした。素材の高級感と拭ける点は良いが、値段の割には、という感想。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20210911:df9c067f:o20210830:s4'),
('cellutane-a387-dog-step-4dan','滑るという声を承知のうえで、若い犬なので購入したが、実際に少し滑る。ヴィンテージグレーは写真より濃い。サイズは大きいがダックスの胴の長さを考えれば妥当で、子どもが乗ると早くへたりそうな柔らかさだという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000012/1.1/','rakuten','350591_10000012:20220903:482b8f69:o20220825:s4')
)
INSERT OR IGNORE INTO review_sources(review_id,source_type,source_url,source_platform,source_review_id)
SELECT r.id,s.source_type,s.source_url,s.source_platform,s.source_review_id
FROM new_sources s
JOIN reviews r ON r.product_id=s.product_id AND r.summary=s.summary;

WITH new_sources(product_id,summary,source_type,source_url,source_platform,source_review_id) AS (
VALUES
('kirara-dog-slope-wide','膝蓋骨脱臼のあるチワワの足を守るため、ゆるい傾斜のものを探して2段を購入。勢いをつけなくても歩いて登れ、耐久性もあると感じている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20260330:3fe8fea4:o20260125:s5'),
('kirara-dog-slope-wide','今年10歳のポメラニアンの先を考えて初めて導入し、教えながら少しずつ使えるように。高さ28cmの3段Aがソファに合い、段差もきつくない。カバー生地のよれが気になって星4にした。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20261117:a3c75407:o20261110:s4'),
('kirara-dog-slope-wide','フローリングに直置きすると裏の滑り止めは弱め。軽くて移動は楽な一方、昇り降りで少し動いて不安定に感じる。降りるときはスロープを飛び越えてしまうので、慣れてほしいとのこと。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20261024:9b791ff8:o20261020:s4'),
('kirara-dog-slope-wide','高さ40cmの3段B。12歳のトイプードルは手を添えれば登れるが、降りるときは飛び降りてしまい、練習しても使ってもらえなかった。本体はしっかりしているものの軽い。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20261013:eb3b000c:o20261010:s4'),
('kirara-dog-slope-wide','9歳のキャバリアの膝の予防に、3段Bを2台並べて横からの飛び降りを防いでいる。ソファとほぼ同じ高さで初日から無理なく使え、4歳の子は遊具のように駆け上がる。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20261004:2bfb9be9:o20261001:s5'),
('kirara-dog-slope-wide','使い始めて2か月。慣れるまで時間がかかり、15歳のトイプードルはいまは降りるときだけ使って、上りはまだ跳び上がる。軽くてずれやすいのが気になるが、降りるときだけでも使ってくれて良かったという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20260524:9d120885:o20260305:s4'),
('kirara-dog-slope-wide','フレンチブルドッグの子犬のソファ用。おやつで練習するとすぐ使ったが、降りる側が少し急で、お腹で滑るように降りている。ファスナーが気になっていたずらするので中にしまい込んだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20260304:fab9f1d0:o20260303:s4'),
('kirara-dog-slope-wide','13歳のトイプードル用。最初は使いこなせなかったが、いまは傾斜をすたすた駆け上がり、体に負担をかけずに済んでいる。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20260104:925c2fc7:o20251210:s5'),
('kirara-dog-slope-wide','ヘルニアの手術歴があるダックスフンド用に2段を。ソファへの乗り降りに無理がないのがありがたいそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20260928:482b8f69:o20260925:s5'),
('kirara-dog-slope-wide','ソファから飛び降りる子犬のミニチュアダックスのため、背の高い3段Bを選択。ソファの色と合い、部屋にもおしゃれに収まった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138894/1.1/','rakuten','213464_10138894:20261028:04225c20:o20261025:s5'),
('sumica-a242-pet-step','白内障で目が見えない16歳のチワワ用に買い替え。前の階段は踏み面が狭く、下りで転げ落ちることがあった。最初の数日は体を支え、1週間ほどで自力で上り下りできるようになった。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20181118:03a5f57f:o20181103:s5'),
('sumica-a242-pet-step','収納ボックスで代用していた高いベッドへの段差用。設置するとすぐ喜んで使った。ファスナーが内側にあって噛まれにくく、布カバーで滑りにくい。毛はかなり付くが、安全を優先してこれにして正解だったという。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20220422:0781beef:o20220412:s5'),
('sumica-a242-pet-step','届いた直後は表示の高さ30cmに届かず25cmほどで星3にしたが、1か月使って犬が使いやすそうなので星5に改めた。1歳の子どももソファの上り下りに使っているとのこと。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20221124:482b8f69:o20221122:s5'),
('sumica-a242-pet-step','4kg弱のカニンヘンダックス。潰れた状態で届いたが、2週間ほどで各段が約10.5・20・29.5cmに戻った。硬さはほどよく、夜も見やすい色で良かった。興奮するとソファから飛び降りそうになるので注意している。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20240202:482b8f69:o20240120:s5'),
('sumica-a242-pet-step','合成レザーの階段で滑って落ち、大けがをしたチワワのため布製を選んだ。すぐ膨らみ滑りにくいが、半年ほどで生地が削れて糸が出て、その糸を食べてしまうので処分した。カバーだけ交換できれば、と書いている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20220412:482b8f69:o20220410:s4'),
('sumica-a242-pet-step','胴が長いので3段を選んだ9歳のミニチュアダックス。少し噛む癖があるがちぎれる心配はなさそう。勢いよく降りて転びかけてからは横向きに降りるようになった。色は思ったより黄色みが強かった。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20210514:5bb838f8:o20210509:s4'),
('sumica-a242-pet-step','2.7kgの犬なら沈まないが、大きい犬だと沈んで登るときに膝へ負担がかかりそう、という見立て。圧縮で布団のように小さく届き、カバーは薄いパイル地で滑りにくそう。天面が擦れて傷まないかを気にしている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20190919:482b8f69:o20190906:s4'),
('sumica-a242-pet-step','他社品は座面が狭くて使わなかった7kgの柴犬。超小型犬の口コミが多く沈むか心配したが沈み込みはなく、一段ごとが低くて登りやすい。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20240312:482b8f69:o20240310:s5'),
('sumica-a242-pet-step','シニアのポメラニアン（4kg）用に買ったのに、2.5kgのチワワのほうがよく使っている。人が片足で乗るとよく沈むがすぐ戻る。噛み防止のためか、チャックは奥に入り込んでいて分かりにくい。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20230309:482b8f69:o20230225:s5'),
('sumica-a242-pet-step','10歳を過ぎて幅の狭い階段や急なスロープがつらそうになったダックスのため、幅広のこちらに。もともと慣れていたのでスムーズに使えたが、高さがもう少しあればうれしいという。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/268789_10003078/1.1/','rakuten','268789_10003078:20230422:482b8f69:o20230415:s4'),
('petfun-dog-step-2dan','シニアになったポメラニアン2匹のため、リビングとダイニングの間にある30cmの段差に設置。すぐに上り下りでき、洗濯できるのも使いやすそうだと感じている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20261122:9b892f2a:o20261119:s5'),
('petfun-dog-step-2dan','犬と猫が走り回ってもずれにくい滑り止め。圧縮で届き、30分ほどで元の形に戻った。防水カバーのせいか犬が少し滑るが、二重の防水カバーは安心で、価格はやや高めでも満足している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20251203:482b8f69:o20251126:s4'),
('petfun-dog-step-2dan','7kgの犬が乗っても支えてくれる厚みと弾力があり、においも気にならない。すぐ乗ってベッド代わりにしているが、階段としてはまだ使っておらず、幅が広いので足元は不安になりにくそうだと見ている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20260510:e9f36962:o20260505:s4'),
('petfun-dog-step-2dan','高さ52cmのベッドへ上り下りするチワワ用。勢いよく使うと防水カバーが滑って怖がったので、バスタオルで覆ったところ滑らなくなった。色は写真どおりのきれいなグレー。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20251212:0209a275:o20251208:s5'),
('petfun-dog-step-2dan','4kgのトイプードルがベッドの上り下りに使うようになり、負担をかけずに済むので安心だとしている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20260727:a71010de:o20260720:s5'),
('petfun-dog-step-2dan','足腰が弱ってきた13歳のチワワ。段差がちょうど合うようで、無理なく登れている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20260726:23a6b021:o20260715:s5'),
('petfun-dog-step-2dan','初めてのステップで、カニンヘンダックスはまだ使ったり使わなかったり。おやつで慣らしつつ、慣れたら買い足しも考えている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20260620:482b8f69:o20260518:s5'),
('petfun-dog-step-2dan','ソファ用の1台がうまくいったので、より高いベッド用に2台を追加して3段に。2.5kgの犬は今回もスムーズに上り下りし、足への負担がなさそうで安心している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20260617:482b8f69:o20260613:s5'),
('petfun-dog-step-2dan','2頭目を迎えて粗相が増え、撥水のステップを探して購入。外カバーも内カバーも撥水で、さっそくおしっこをされたが全く染みていなかった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20260610:482b8f69:o20260607:s5'),
('petfun-dog-step-2dan','飛び上がるのをためらうようになった犬が昼寝するベッド用。軽くてしっかりした素材だが、届いて2日で登ったのは1回だけで、慣れるのを待っている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000343/1.1/','rakuten','415921_10000343:20260314:0f45122c:o20260310:s4'),
('kirara-dog-step-storage-3dan','ベッドから頻繁に飛び降りるダックスフンドの脚や腰が心配で購入。段差は10cmで昇降が楽そうに見え、収納ボックスとして使える点も評価している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20261028:482b8f69:o20261026:s4'),
('kirara-dog-step-storage-3dan','ボーダーコリーの子犬がすぐに使って上がってくるようになった。成長後も物入れとして役立ちそうな一方、走って上り下りするとクッションフロアの上で本体を蹴り飛ばしてしまうので、底に滑り止めが欲しいという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20260310:a4779f47:o20260308:s4'),
('kirara-dog-step-storage-3dan','収納は便利だが、男の子の犬はふたを噛んだり外したりして遊んでしまう。女の子はそうしないので、ふたが外れにくい作りなら長持ちしそうだと書いている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20260208:482b8f69:o20260124:s4'),
('kirara-dog-step-storage-3dan','シニア犬用に購入し、値段を考えれば満足。降りるときに前へ少し揺れたが、3段目の収納に重りを入れて解消した。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20250611:482b8f69:o20250605:s5'),
('kirara-dog-step-storage-3dan','16kgのコーギーでもしっかり上り下りできている。本体がとても軽いので、フードなど重い物を入れて安定させている。手頃な価格ゆえに耐久性は少し心配だという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20230510:c228eae4:o20230425:s4'),
('kirara-dog-step-storage-3dan','膝蓋骨脱臼と診断された9歳・4.5kgのマルチーズ×チワワのソファ用。最初は怖がったが、抱っこで乗せるのを数回繰り返すと少しずつ使うように。安定感があり、収納もそこそこ入る。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20240209:482b8f69:o20240128:s5'),
('kirara-dog-step-storage-3dan','犬が自由にソファへ上り下りでき、おもちゃ入れにもなる。勢いよく使うとふたがずれるのでマジックテープなどで留めるとよく、フローリングでは滑るため滑り止めマットを敷いて落ち着いた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20230519:42a70ae7:o20230515:s5'),
('kirara-dog-step-storage-3dan','11年一緒に暮らす犬が、おやつで覚えていまはベッドに上がるたびに使う。最初はにおいがきつかったがすぐ消えた。軽いので滑り止めマットの上に置き、最上段に1.5Lのペットボトルを入れている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20220813:c6fb8460:o20220808:s5'),
('kirara-dog-step-storage-3dan','前の階段を高く感じて登らなくなった18歳・4kgの小型犬が、すぐ登ってくれた。生地も滑りにくい。グレーの色味は微妙で、においも独特。中に物を入れると安定するとのこと。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20240823:482b8f69:o20240820:s5'),
('kirara-dog-step-storage-3dan','もうすぐ15歳になる3.6kgのミニチュアダックスがベッドから飛び降りるようになり、急いで購入。最初はへっぴり腰でもすぐ慣れた。作りはしっかりしているが、あと半年もてば、と耐久性にはやや不安を残している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20240316:be6705a5:o20240310:s4')
)
INSERT OR IGNORE INTO review_sources(review_id,source_type,source_url,source_platform,source_review_id)
SELECT r.id,s.source_type,s.source_url,s.source_platform,s.source_review_id
FROM new_sources s
JOIN reviews r ON r.product_id=s.product_id AND r.summary=s.summary;

WITH new_sources(product_id,summary,source_type,source_url,source_platform,source_review_id) AS (
VALUES
('kirara-dog-step-storage-3dan','別の店の2段ではベッドに高さが足りず、降りるのを怖がっていた。3段のこちらに替えるとスムーズに乗り降りし、6kgの犬が乗ってもしっかりしている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/213464_10138257/1.1/','rakuten','213464_10138257:20240627:6ad36a01:o20240515:s5'),
('nedogko-dog-step-low','ソファに登れても降りられなかった子犬のコーギーが、いまは軽快に上り下り。短足の犬にもやさしい低さで、噛まれても生地が破れず、ファスナーを隠せるのも安心材料になっている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20250126:75f5f113:o20241221:s5'),
('nedogko-dog-step-low','膝の手術後のマルチーズ2匹のためにロータイプを選び、生地とウレタンの固さも合った。高さ約27cmのベッドにはロー1つで足り、約35cmのソファには2つ重ねる。畳や絨毯の上では底の滑り止めでも動くので、はがせるテープで固定している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20220130:4733cb26:o20211205:s4'),
('nedogko-dog-step-low','ヘルニアと診断された11歳のビーグルのため、ロー2つを組み合わせて3段に。おやつで誘導して覚え、いまは自分で上り下りする。ステップを通らないと行けない位置に置いたのも工夫のひとつ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20220801:1776cdda:o20220728:s5'),
('nedogko-dog-step-low','胴長短足の8歳のプードル。一番上の段は奥行きが狭くて怖がり、上段には乗らずにソファへ飛び乗ってしまう。色違いを2つ並べたら色の差が目立ったのも残念だったという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20220908:482b8f69:o20220905:s4'),
('nedogko-dog-step-low','段の間隔が狭い3段ステップでは踏み外していたシニアのダックス。間隔に余裕ができて登りやすくなったが、後ろ足のまひで最後の足が引っかかることがあり、タオルで坂を作ることを考えている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20220312:91aa4d65:o20220218:s5'),
('nedogko-dog-step-low','白内障もある14歳のトイプードル用に、高さ15cmのステップから買い替えて2個で3段に。踏み込みが広く調子はよいが、前のレザーより汚れが拭きにくく、軽すぎて動くのが惜しい点として挙がっていた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20211028:f4739d8c:o20211020:s4'),
('nedogko-dog-step-low','約7kgのダックスは、上りはいまも飛び乗るが、降りるときはステップを使うようになった。段が短いのか降りにくそうで、もう少し長さがあるとよいという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20240122:482b8f69:o20240113:s5'),
('nedogko-dog-step-low','段差で滑り落ちた老犬のダックスのために買ったが、バリケードと思ったのか、いまのところ登らない。段が低く滑りにくい点、マットが硬めな点は気に入っている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20230217:6d42985e:o20230210:s5'),
('nedogko-dog-step-low','階段状にすると上の段が短くて嫌がったが、1段に広げたら上り下りするように。くつろぎや昼寝の場所にもなっていて、2段目が長ければリピートしたいそうだ。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20230815:01c7e810:o20230725:s4'),
('nedogko-dog-step-low','ベッドに上がれなくなりつつある18歳の犬のため、薄くて柔らかめの段で高さを調整。形が変わって戸惑う場面はあるが、滑って危なっかしい感じはなくなった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20240721:7e2425c7:o20240711:s4'),
('nedogko-dog-step-low','ミニチュアダックス2頭と猫1匹の家で、2頭が同時に乗っても安全なように2つ買い足した。猫が爪をといでもきれいで合皮より丈夫だが、カバーは洗うと乾きにくく少し縮む。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/355438_10000381/1.1/','rakuten','355438_10000381:20220422:f9a4766e:o20220410:s4'),
('cellutane-a385-dog-step-2dan','飛び降りがなくなり、犬も快適に使っている。高さ約33cmの幅広タイプで、ベッドと合わせて3段の階段のように。生地のよれと、底が滑り止め仕様でない点は残念で、別に滑り止めを敷くと勢いよく上っても動かなくなった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/','rakuten','350591_10000032:20200703:1a55d8c9:o20200605:s5'),
('cellutane-a385-dog-step-2dan','ソファへジャンプして危ない生後3か月のチワプー用。届いてすぐ使い始め、暑い日は1段目のひんやりした感触を気に入って昼寝している。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/','rakuten','350591_10000032:20200511:482b8f69:o20200428:s5'),
('cellutane-a385-dog-step-2dan','前の幅が狭く段差の高いステップは上りにしか使わなかった5kgのマルプー。こちらは段差がゆるく幅もあり、怖がらずに上り下りできた。大きいが一人で動かせる重さだという。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/','rakuten','350591_10000032:20180521:73ab8aab:o20180517:s5'),
('cellutane-a385-dog-step-2dan','トイプードル2匹のうち1匹はすぐ使い、警戒したもう1匹もおやつで一段ずつ慣らすとすぐ覚えた。滑ってはいないが、念のためビニール床対応の犬用滑り止めワックスを自己責任で塗った。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/','rakuten','350591_10000032:20221110:f186b35d:o20221031:s5'),
('cellutane-a385-dog-step-2dan','慎重な性格で最初は使わず、おやつで誘導していたが、ソファ用の布をかぶせたら使い始めた。素材自体は滑りやすくないが、カバーがあると安心するらしく自作したそうだ。軽くて移動は楽、価格はやや高め。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/','rakuten','350591_10000032:20180705:a00c9dd3:o20180630:s5'),
('cellutane-a385-dog-step-2dan','小上がりの和室に飛び乗る子犬に、早いうちから慣れてほしくて購入。まだおやつで釣らないと乗らない。奥行きを考えずに買ったので縦に長く、部屋に圧迫感がある。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/','rakuten','350591_10000032:20200123:482b8f69:o20200118:s4'),
('cellutane-a385-dog-step-2dan','ソファからうまく着地できなくなったハイシニアのマルチーズ。簡易の段差と併用して時々登っていて、降りるのも覚えてほしいところ。滑るかと思ったがクッションの弾力で問題なかった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/','rakuten','350591_10000032:20201017:0b10bf42:o20201009:s5'),
('cellutane-a385-dog-step-2dan','左後ろ足が弱い犬のために購入。商品は良いと思うが、まだ警戒して近寄らず、おやつやおもちゃで少しずつ教えていく予定。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/350591_10000032/1.1/','rakuten','350591_10000032:20210125:482b8f69:o20210116:s5'),
('chikyutonya-dog-step-wide55','後ろ脚の踏ん張りが弱くなった大型の高齢犬のため、ベランダへの段差に設置。幅広のハードタイプなので、大型犬が乗っても沈み込まず安心して使えている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20260426:af4effe3:o20260419:s5'),
('chikyutonya-dog-step-wide55','変形性脊椎症のある12歳・4kgのトイプードル。以前のスロープはわずかなぐらつきを嫌がり、とくに上りで使わなかった。幅広で重さのあるこちらは初日から上り下りでき、汚れもさっと拭ける。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20260123:2c9ae50d:o20251216:s5'),
('chikyutonya-dog-step-wide55','走り回ってソファまで使う10kgのコーギーの段差対策。まったくずれずしっかりしているが、グレーが思ったより濃く、ホワイトにすればよかったと少し後悔している。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20260224:dd89d976:o20260210:s5'),
('chikyutonya-dog-step-wide55','作りはしっかりしているが、うちの犬には上段の幅が足りないようで、2つ買い足して幅を広げる予定。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20260729:27448feb:o20260725:s4'),
('chikyutonya-dog-step-wide55','シニアのチワワとパピーがいて、パピーのソファからの飛び降りを止めたくて、沈まない硬めを選んだ。2匹ともすぐ使って飛び降りがなくなった。黒はほこりや毛が目立つが、インテリアには合う。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20250912:f9699d3f:o20250904:s5'),
('chikyutonya-dog-step-wide55','幅の狭い階段はあるが、とっさに飛び降りてしまうダックス。ヘルニアや脚が心配で、ワイドで段差の低いこれを選んだ。1つでは高さが少し足りないので、もう1つ買う予定。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20250703:9c213864:o20250625:s5'),
('chikyutonya-dog-step-wide55','約3kgのポメラニアン。布カバーの3段がぼろぼろになり、販売終了だったので乗り換えた。3段にするには2つ要り少し高くなったが、幅広で硬さもある。160サイズで宅配ボックスに入らず、営業所で受け取った。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20251011:7611a16d:o20251008:s5'),
('chikyutonya-dog-step-wide55','いままでの階段を登れなくなった11歳の犬のため、2つで3段にして使用。幅が広く硬めなので沈まず、一段ずつしっかり登れている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20250513:80f57a56:o20250505:s5'),
('chikyutonya-dog-step-wide55','生後4か月のマルチーズがすぐに使い方を理解し、飛び降りをしなくなった。膝を守りながら暮らせそうだと感じている。','public_buyer_review_summary','https://review.rakuten.co.jp/review/item/1/306432_10004135/1.1/','rakuten','306432_10004135:20250623:2c90e37b:o20250616:s5'),
('petfun-urbantail-wood-slope','階段を怖がっていたトイプードルが、おやつを使った約3週間の練習で4段を自分から使うように。木の土台がしっかりしていて克服に向いていた。階段下のスペースは怖がって入らず、防災袋の置き場にする予定。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260322:60c272a9:o20260222:s5'),
('petfun-urbantail-wood-slope','飛び降り防止に3段を設置。リビングでも浮かない見た目だが、角度がもう少しゆるく、幅の広いタイプもあれば、と星4。設置後も途中から飛び降りるので、使う癖づけを続けている。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260604:2fe29f33:o20260507:s4'),
('petfun-urbantail-wood-slope','3段なのに4段用の説明書が入っていて穴の数に戸惑い、動画とも手順が少し違ったが、一人で約1時間で組み立てた。高いベッドから飛び降りる3kgのプードルが数日で使うように。天板がはずみで外れることがあり、星を1つ減らした。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260306:482b8f69:o20260221:s4'),
('petfun-urbantail-wood-slope','今年17歳になるジャックラッセルがベッドやソファに上がれるように購入し、いまは登る練習中。作りはしっかりしていて、組み立ても簡単だった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260606:482b8f69:o20260523:s4'),
('petfun-urbantail-wood-slope','傾斜が急でやや滑るものの、臆病な13歳のトイプードルもどうにか登れるようになった。作りはしっかりしていて安心感がある。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260925:482b8f69:o20260823:s4'),
('petfun-urbantail-wood-slope','なだらかなスロープで、14歳のトイプードルが使えている。2歳の子も飛び乗って使うが、しっかりしていて問題ない。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260821:80b9f777:o20260815:s5'),
('petfun-urbantail-wood-slope','女性一人でも組み立てられた。犬は最初おそるおそるで、少しずつ慣れてきたがまだ降りることはできない。飼い主が自分で試すと急斜面に感じて怖かった。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260520:482b8f69:o20260414:s4'),
('petfun-urbantail-wood-slope','ネジ穴が2か所開いておらず、自宅の電動ドライバーでなんとか取り付けた。昇降用に買ったのに、クッションが心地よいのか犬は一番上でくつろいでいる。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260201:482b8f69:o20260124:s4'),
('petfun-urbantail-wood-slope','ネジが入らない穴があり耐久性が不安。足の悪い12歳のチワワは登り降りで滑り、百均の滑り止めを貼っても自分からは使わない。傾斜の急さが原因と見ていて、他社のゆるいスロープは使えたという。拭けて滑りにくい素材を望んでいた。','public_buyer_review_summary','https://review.rakuten.co.jp/item/1/415921_10000353/1.1/','rakuten','415921_10000353:20260929:482b8f69:o20260906:s1')
)
INSERT OR IGNORE INTO review_sources(review_id,source_type,source_url,source_platform,source_review_id)
SELECT r.id,s.source_type,s.source_url,s.source_platform,s.source_review_id
FROM new_sources s
JOIN reviews r ON r.product_id=s.product_id AND r.summary=s.summary;
